S.bass=(S.bass||0)*.93+(A.bass||0)*.07;

// ---- dramaturgy: a colourist working the shot over minutes ----
let gM=1, axisR=.011;
if(act==='breathe'){ gM=.52+.72*(.5+.5*Math.sin(T*.028))+.16*Math.sin(T*.067+1.3); }
