// the stock's hue drifts a few degrees the way a real grade never sits perfectly still
const hd=6.5*Math.sin(T*.023)+3*Math.sin(T*.059+1.1);
const HG=md(H0+hd,360);

// ---- 1. saturation: how much colour the process leaves alive ----
let satTgt, castC, castA, mulC, mulA, scrC, scrA;
if(sty==='day_for_night'){ satTgt=.42; castC=hsb(md(HG+188,360),62,60); castA=.44*E;
  mulC=hsb(md(HG+192,360),58,52); mulA=.34*E; scrC=hsb(md(HG+196,360),40,26); scrA=.30*E; }
