else if(sty==='velvia'){ satTgt=1; castC=hsb(md(HG+6,360),64,70); castA=.07*E;
  mulC=hsb(md(HG+188,360),34,80); mulA=.26*E; scrC=hsb(md(HG+2,360),50,34); scrA=.10*E; }
else { satTgt=0; castC=hsb(md(HG,360),82,64); castA=.94*E;                       // sodium vapour
  mulC=hsb(md(HG+4,360),44,88); mulA=.09*E; scrC=hsb(md(HG+10,360),58,26); scrA=.16*E; }

// velvia is the one stock here that ADDS colour: a fully-saturated source under the
// 'saturation' op pushes the frame's chroma up instead of bleeding it out
if(sty==='velvia') fill('saturation',hsb(md(HG,360),100,60),cl(.66*E,0,.82));
