  const wx=(ax+.20*Math.sin(T*.061)+.09*Math.sin(T*.143+1.7)+.05*Math.sin(T*.229))*W;
  const wy=(ay+.16*Math.cos(T*.053+.6)+.08*Math.sin(T*.127+2.3)+.04*Math.sin(T*.191))*Hh;
  const wr=u*(.40+.16*Math.sin(T*.031))*sc;
  const wc=hsb(md(HG+12,360),40,98);
