  const wa=cl((.10+.09*dns)*E*(1+.22*S.rms),0,.15);
  gg.addColorStop(0,rs(wc,wa)); gg.addColorStop(.55,rs(wc,wa*.42)); gg.addColorStop(1,rs(wc,0));
  dc.globalCompositeOperation='screen'; dc.fillStyle=gg; dc.fillRect(0,0,W,Hh);
  // and its inverse — the edges roll off the way any real window does
  const dc2=hsb(md(HG+184,360),44,66);
  const g2=dc.createRadialGradient(wx,wy,wr*.45,wx,wy,wr*1.9);
  g2.addColorStop(0,rs(dc2,0)); g2.addColorStop(1,rs(dc2,cl(.20*dns*E,0,.24)));
  dc.globalCompositeOperation='multiply'; dc.fillStyle=g2; dc.fillRect(0,0,W,Hh);
  dc.globalCompositeOperation=oldOp;
}

// ---- 5. gate density: the lamp is never perfectly steady (slow, ~±3%, cannot read as flicker) ----
{ const dv=.030*Math.sin(T*.083)+.016*Math.sin(T*.197+1.4)+.009*Math.sin(T*.331+2.9);
  if(dv>0) fill('screen',hsb(md(HG+8,360),30,90),cl(dv*E*.9,0,.05));
  else fill('multiply',hsb(md(HG+6,360),24,86),cl(-dv*E*1.5,0,.07)); }

